const body = $json.body ?? $json;
const now = new Date().toISOString();
return [{
  json: {
    id: body.id || body.message_id || '',
    tenant_id: body.tenant_id || 'peskids',
    sender_contact: body.sender_contact || body.from || '',
    sender_name: body.sender_name || 'Unknown',
    audio_url: body.audio_url || '',
    audio_duration_seconds: body.audio_duration_seconds || 0,
    channel: body.channel || 'web',
    direction: body.direction || 'inbound',
    external_id: body.external_id || body.externalId || null,
    created_at: body.created_at || now,
    received_at: now
  }
}];
